async ({ gh: { issueView, issueEdit, issueClose } }) => {
  const body = JSON.parse((await issueView(383, { json: ["body"] } as any)).stdout).body as string;
  const ticked = body.replaceAll("- [ ] ", "- [x] ");
  const e = await issueEdit(383, { body: ticked } as any);
  const c = await issueClose(383, { comment: "Shipped in [v0.37.0](https://github.com/cv/pit/releases/tag/v0.37.0) (release PR #388, tracked in #387). Every item above landed in #385 and #386." } as any);
  return { e: e.code, c: c.code, out: (c.stdout + c.stderr).slice(-200) };
}
